import{_ as a,o as i,c as e,a2 as r}from"./chunks/framework.Ca9F9Y59.js";const l="/k3gdb/assets/%E7%81%B5%E6%B1%90%E6%98%9F%E8%BD%A8.dn2eY_4T.png",o="/k3gdb/assets/%E6%B3%B0%E8%BF%A6ai%E8%BE%85%E5%8A%A9%E6%95%99%E5%AD%A6.nsaN4ZRB.png",d="/k3gdb/assets/tutor%E7%B3%BB%E7%BB%9F.B4-L6tVe.png",s="/k3gdb/assets/AI-Tutor%E6%80%BB%E4%BD%93%E6%9E%B6%E6%9E%84.CEm4TWru.png",m=JSON.parse('{"title":"ai辅助教学平台","description":"","frontmatter":{},"headers":[],"relativePath":"2026-11-19-大赛-ai辅助教学系统项目.md","filePath":"2026-11-19-大赛-ai辅助教学系统项目.md"}'),p={name:"2026-11-19-大赛-ai辅助教学系统项目.md"};function n(h,t,_,c,E,u){return i(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ai辅助教学平台" tabindex="-1">ai辅助教学平台 <a class="header-anchor" href="#ai辅助教学平台" aria-label="Permalink to &quot;ai辅助教学平台&quot;">​</a></h1><h2 id="灵汐星轨" tabindex="-1">灵汐星轨 <a class="header-anchor" href="#灵汐星轨" aria-label="Permalink to &quot;灵汐星轨&quot;">​</a></h2><p>灵汐把课程学习、AI 辅导、答题和实验放在同一个工作台里。教师导入教材后，系统生成知识图谱并存入 Neo4j，供助教按需检索。学生的对话、答题和掌握度保存在 SQLite，编译和运行则通过独立的浏览器终端完成。</p><p>主要功能模块：</p><ol><li>教学工作台： 提供学生和教师的统一操作界面，包括课程学习、AI 助教、答题和实验终端。</li><li>课程与知识图谱： 利用 AI 分析教材，提取知识点及其关系，使用 Neo4j 保存知识图谱。</li><li>AI 教学： 提供智能问答、答案评分和知识掌握度评价。</li><li>实验工作区： 为学生提供独立源码副本、在线终端和实验测试。</li><li>数据管理： 使用 SQLite 保存学生会话、答题记录和学习情况。</li></ol><p><img src="'+l+'" alt="灵汐星轨"></p><p>核心特点： 通过 AI 和知识图谱组织教学内容，结合学生学习记录，实现智能辅导与学习评价。</p><h2 id="泰迦-proj20" tabindex="-1">泰迦 Proj20 <a class="header-anchor" href="#泰迦-proj20" aria-label="Permalink to &quot;泰迦 Proj20&quot;">​</a></h2><p>泰迦围绕一次内核实验展开。学生在浏览器点击运行，Node.js 调用 Cargo 编译内核，再启动 QEMU。内核输出的实验标记被解析成事件，实时显示在网页时间线上。学生提问时，AI 助教可按需读取当前源码和本次实验的运行证据，再调用火山方舟给出指导。</p><p>主要功能模块：</p><ol><li>实验工作台： 提供实验任务、源码查看、运行操作和结果展示。</li><li>实验运行管理： 通过 Cargo 编译 Rust 内核，使用 QEMU 模拟 RISC-V 计算机运行内核。</li><li>运行事件收集： 收集内核串口输出，将实验信息整理成结构化事件，并实时展示。</li><li>实验记录： 保存当前和最近完成的实验记录，支持历史回放。</li><li>AI 助教： 根据需要读取学生源码、Git 修改记录和实验运行结果，分析问题并提供指导。</li></ol><p><img src="'+o+'" alt="泰迦ai辅助教学"></p><p>核心特点：通过真实内核运行和实验过程记录，让 AI 能够结合学生的代码与实际运行结果进行分析和指导。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>灵汐星轨侧重于教学过程的智能化，利用知识图谱和 AI 帮助学生学习、评价学习效果；泰迦 Proj20 侧重于实验过程的智能化，通过真实内核运行和过程记录，让 AI 能够理解学生的实践情况。</p><h2 id="当前系统" tabindex="-1">当前系统 <a class="header-anchor" href="#当前系统" aria-label="Permalink to &quot;当前系统&quot;">​</a></h2><p>系统以学生的一次实验学习过程为主线。</p><p>学生首先阅读内核源码并预测实验结果，然后由实验执行器启动 QEMU，运行 rCore 内核。</p><p>实验结束后，系统采集运行日志和结果，对实验数据进行完整性验证，并将实际结果与学生之前保存的预测进行比较。</p><p>最后，AI 基于已经验证的实验事实解释运行现象，帮助学生理解预测与实际结果之间的差异。</p><p><img src="'+d+'" alt="tutor系统"></p><h2 id="可优化的功能" tabindex="-1">可优化的功能 <a class="header-anchor" href="#可优化的功能" aria-label="Permalink to &quot;可优化的功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前 MVP 0.3</th><th>最终目标</th></tr></thead><tbody><tr><td>Web 学习界面</td><td>Web + VS Code + CLI</td></tr><tr><td>ch1 单章节实验</td><td>多章节、模块化实验课程</td></tr><tr><td>源码阅读与三维预测</td><td>完整知识组织与前后测</td></tr><tr><td>QEMU 实验和证据采集</td><td>更丰富的调试与运行时观测</td></tr><tr><td>FakeGateway / DeepSeek</td><td>完整 AI 教学智能层</td></tr><tr><td>基础预测偏差解释</td><td>学生模型、学习诊断、动态教学决策</td></tr><tr><td>基础实验反馈</td><td>持续学习评价与路径调整</td></tr></tbody></table><h2 id="总体架构" tabindex="-1">总体架构 <a class="header-anchor" href="#总体架构" aria-label="Permalink to &quot;总体架构&quot;">​</a></h2><p>一个能够了解学生学习情况、组织真实内核实验、分析实验结果，根据学生掌握程度动态调整教学内容的智能教学平台</p><ol><li>学习诊断：了解学生已有知识和薄弱环节。</li><li>理论学习与源码阅读：结合知识点和真实 Rust 内核源码理解原理。</li><li>实验实践：学生修改代码，使用 Cargo、测试工具和 QEMU 完成实验。</li><li>运行证据采集：获取编译结果、测试结果、源码变化和运行时信息。</li><li>AI 个性化辅导：根据知识状态、源码状态和运行状态诊断问题，提供分层提示和解释。</li><li>学习评价：通过后测、实验完成情况和独立解决问题的表现评估学习效果。</li><li>动态调整学习路径：根据评价结果调整下一阶段学习内容。</li></ol><p><img src="'+s+'" alt="AI-Tutor总体架构"></p>',27)])])}const A=a(p,[["render",n]]);export{m as __pageData,A as default};
